def resolve(name, zone, max_hops=8):
    chain = [name]
    ttls = []
    current = name
    for _ in range(max_hops):
        if current not in zone:
            raise LookupError(f"sin registro para {current}")
        rtype, value, ttl = zone[current]
        ttls.append(ttl)
        if rtype == "A":
            return value, chain, min(ttls)
        chain.append(value)
        current = value
    raise RecursionError("cadena de CNAME excede el limite")

zone = {
    "app.example.com": ("CNAME", "lb.example.com", 300),
    "lb.example.com": ("CNAME", "edge.example.com", 60),
    "edge.example.com": ("A", "20.51.3.10", 30),
}

ip, chain, ttl = resolve("app.example.com", zone)
print("Cadena:", " -> ".join(chain))
print("IP resuelta:", ip)
print("TTL efectivo (minimo de la cadena):", ttl)

loop_zone = {
    "a.example.com": ("CNAME", "b.example.com", 60),
    "b.example.com": ("CNAME", "a.example.com", 60),
}
try:
    resolve("a.example.com", loop_zone, max_hops=5)
except RecursionError as exc:
    print("Error esperado:", exc)
